let atlas,entries=[],active=null,cursor=3,kind='parts',snap=true,reference=false,busy=false,selectedPiece=null,undo=[],xrMode=null,pendingCenter=0,lastTime=0,notice='Gotowe',restoring=false,backplate=false,readable=true,menuTab=2,assistText='',lastMenuTime=0,layoutMode='free',freeGroups=[],activeFree=null,cutSide=0,category='all',catalogSort='folio',previewPart=-1,splitAxis='x',splitCount=2,editAxis=1,previewTarget=null;
