function say(t){notice=t;$('#status').textContent=t;drawMenu();}
function dispose(root){const materials=new Set(),textures=new Set();root.traverse(o=>{o.geometry?.dispose();const original=originalGeometry.get(o);if(original&&original!==o.geometry)original.dispose();const pair=materialPairs.get(o);for(const m of [o.material,pair?.original,pair?.flat].flat().filter(Boolean)){materials.add(m);if(m.map)textures.add(m.map);}});materials.forEach(m=>m.dispose());textures.forEach(t=>t.dispose());}
function releaseAll(){for(const h of hands)release(h,false);}
function capture(){return {format:'voynich-quest',version:6,study:study.capture(),scale:'metres in workspace; original physical scale unknown',entries:entries.map(e=>({id:e.id,scan:e.scan,kind:e.kind,part:e.part,root:relativeTransform(e.root,content),cluster:relativeTransform(e.cluster,e.origin),pieces:e.pieces.map(p=>capturePiece(e,p))})),freeGroups:freeGroups.map(g=>({id:g.id,transform:relativeTransform(g.root,content)})),layoutMode,snap,reference,backplate,readable};}
function capturePiece(e,p){const r=freeMembership.has(p)?{name:p.name,joined:false,freeGroup:freeMembership.get(p).id,transform:relativeTransform(p,freeMembership.get(p).root)}:pieceRecord(e,p);return {...r,pinned:!!p.userData.pinned,boardId:p.userData.boardId||null,visible:p.visible,sourceName:p.userData.sourceName||null,cut:p.userData.cut?{...p.userData.cut}:null};}
function persist(){if(restoring)return;try{localStorage.setItem('voynich-quest-v1',JSON.stringify(capture()));}catch(e){say('Brak miejsca na zapis. Wyeksportuj projekt JSON.');}}
function remember(){if(restoring)return;undo.push(capture());if(undo.length>20)undo.shift();}
function setActive(e,piece=null){active=e;selectedPiece=piece;if(piece&&freeMembership.has(piece))activeFree=freeMembership.get(piece);updateVisibility();drawMenu();if(piece)showSelectedPreview();}
function removeEntry(e){if(!e)return;releaseAll();for(const p of e.pieces)detachAny(e,p);content.remove(e.root);dispose(e.root);entries=entries.filter(x=>x!==e);active=entries.at(-1)||null;selectedPiece=null;}
function filteredPages(){return filterCatalog(atlas.pages,category,catalogSort);}
function refreshCatalog(){const pages=filteredPages();if(!pages.includes(atlas.pages[cursor]))cursor=atlas.pages.indexOf(pages[0]);$('#scan').innerHTML='';for(const p of pages){const o=document.createElement('option');o.value=p.id;o.textContent=`f${p.label} · ${p.category}`;$('#scan').append(o);}$('#scan').value=atlas.pages[cursor].id;$('#category').value=category;$('#catalogSort').value=catalogSort;previewPart=-1;refreshParts();updatePreview();study?.filter(pages);drawMenu();}
function nextCard(delta){const pages=filteredPages(),i=pages.indexOf(atlas.pages[cursor]);cursor=atlas.pages.indexOf(pages[((i+delta)%pages.length+pages.length)%pages.length]);$('#scan').value=atlas.pages[cursor].id;previewPart=-1;refreshParts();updatePreview();drawMenu();}
function cycleCategory(){const choices=['all',...catalogCategories(atlas.pages)];category=choices[(choices.indexOf(category)+1)%choices.length];refreshCatalog();}
function refreshParts(){const p=atlas.pages[cursor];$('#previewPart').innerHTML='';const all=document.createElement('option');all.value='-1';all.textContent='Cały rysunek';$('#previewPart').append(all);p.parts.forEach((part,i)=>{const o=document.createElement('option');o.value=String(i);o.textContent=`${i+1}. ${part.label}`;$('#previewPart').append(o);});$('#previewPart').value=String(previewPart);$('#catalogThumb').src=`assets/thumbs/${p.id}.jpg`;$('#catalogThumb').alt=`Skan f${p.label}`;}
function nextPart(delta){kind='parts';$('#kind').value=kind;const n=atlas.pages[cursor].parts.length;previewPart=((previewPart+1+delta)%(n+1)+(n+1))%(n+1)-1;$('#previewPart').value=String(previewPart);updatePreview();}
function previewChoice(){const p=atlas.pages[cursor],part=kind==='parts'&&previewPart>=0?p.parts[previewPart]:null;return {page:p,part,type:part?'fragment':kind,path:part?part.model:kind==='whole'?'assets/manuscript_all.glb':kind==='page'?p.page_model:(p.art_model||p.page_model),label:part?`${previewPart+1}/${p.parts.length} · ${part.label}`:kind==='whole'?'Cały atlas':kind==='page'?'Pełny skan':'Cały rysunek'};}
async function updatePreview(){if(!atlas)return;previewTarget=null;const c=previewChoice();$('#previewCaption').textContent=`f${c.page.label} · ${c.page.category} · ${c.label}`;await preview.load(c.page,c.part,c.path,c.label);}
async function addPreview(){if(busy)return;if(previewTarget&&entries.includes(previewTarget.entry)&&previewTarget.piece.visible){const {entry,piece}=previewTarget;if(entry.pieces.length>=400){say('Limit części w zestawie.');return;}remember();releaseAll();const clone=clonePiece(entry,piece,`${piece.userData.sourceName||piece.name}__copy_${crypto.randomUUID()}`);applyTransform(clone,relativeTransform(piece,entry.origin));if(piece.userData.cut)applyPieceCut(entry,clone,piece.userData.cut);clone.position.x+=.1;setActive(entry,clone);persist();say('Utworzono osobną kopię fragmentu z podglądu.');return;}const c=previewChoice();if(entries.length>=30){say('Limit 30 zestawów.');return;}remember();busy=true;try{const e=await addEntry(c.page.id,c.type,c.part?{part:c.part.id}:null);if(renderer.xr.isPresenting)placeAhead(e);persist();say('Dodano model widoczny w podglądzie.');}catch{say('Nie udało się dodać modelu.');}finally{busy=false;}}

async function addEntry(scan=atlas.pages[cursor].id,type=kind,record=null){
 if(entries.length>=30)throw Error('Limit: 30 zestawów. Usuń jeden lub zapisz i zacznij nową pracownię.');
 const p=atlas.pages.find(x=>x.id===scan);if(!p)throw Error('Nieznany skan');
 const sourcePart=type==='fragment'?p.parts.find(x=>x.id===record?.part):null;if(type==='fragment'&&!sourcePart)throw Error('Nieznany fragment');
 const path=sourcePart?sourcePart.model:type==='whole'?'assets/manuscript_all.glb':type==='page'?p.page_model:(p.art_model||p.page_model);
 const g=await loader.loadAsync(path),root=new THREE.Group(),origin=new THREE.Group(),cluster=new THREE.Group();root.add(origin);origin.add(cluster);cluster.name="Połączone fragmenty";root.name=`${p.label} / ${type}`;const pieces=[...g.scene.children];for(const o of pieces)origin.add(o);
 const bounds=new THREE.Box3().setFromObject(origin),center=bounds.getCenter(new THREE.Vector3()),size=bounds.getSize(new THREE.Vector3());origin.position.sub(center);
 const e={id:record?.id||crypto.randomUUID(),scan,kind:type,part:sourcePart?.id||null,root,origin,cluster,pieces,home:new Map(),joined:new Set(),anchors:new Map(),ref:null,back:null};root.userData={assembly:e.id,scan,kind:type,depth:'interpretive relief',physical_scale:'unknown'};
 for(const o of pieces){o.userData.entryId=e.id;e.home.set(o.name,homeTransform(o));
 const c=new THREE.Box3().setFromObject(o).getCenter(new THREE.Vector3());o.worldToLocal(c);e.anchors.set(o.name,c);
 o.traverse(m=>{if(!m.isMesh)return;originalGeometry.set(m,m.geometry);const original=m.material;const convert=a=>new THREE.MeshBasicMaterial({map:a.map,color:a.color,side:THREE.DoubleSide,transparent:a.transparent,opacity:a.opacity,alphaTest:a.alphaTest,depthWrite:a.depthWrite});const flat=Array.isArray(original)?original.map(convert):convert(original);materialPairs.set(m,{original,flat});m.material=readable?flat:original;});}
 root.scale.setScalar(type==='whole'?1.7/Math.max(size.x,size.y,.1):.65);root.position.set(entries.length%3*.42,1.3,-1.1-entries.length*.07);content.add(root);entries.push(e);
 if(type!=='whole'){
  try{const tex=await new THREE.TextureLoader().loadAsync(`assets/images/${scan}.jpg`);tex.colorSpace=THREE.SRGBColorSpace;const plane=new THREE.Mesh(new THREE.PlaneGeometry(p.width/p.height,1),new THREE.MeshBasicMaterial({map:tex,transparent:true,opacity:.5,depthWrite:false,side:THREE.DoubleSide}));plane.position.z=-.025;plane.visible=reference;plane.userData.reference=true;cluster.add(plane);e.ref=plane;}catch{}
 }
 const back=new THREE.Mesh(new THREE.PlaneGeometry(Math.max(size.x,.05)+.08,Math.max(size.y,.05)+.08),new THREE.MeshBasicMaterial({color:0x101923,side:THREE.DoubleSide}));back.position.copy(center);back.position.z=bounds.min.z-.035;cluster.add(back);e.back=back;back.visible=false;back.userData.reference=true;
 if(record?.root){applyTransform(root,record.root);if(record.cluster)applyTransform(cluster,record.cluster);for(const r of record.pieces){let o=pieces.find(p=>p.name===r.name);if(!o&&r.sourceName){const base=pieces.find(p=>p.name===r.sourceName);if(!base)throw Error('Brak źródła podziału');o=clonePiece(e,base,r.name);}
if(o){o.visible=r.visible!==false;o.userData.pinned=r.pinned===true;o.userData.boardId=r.boardId||null;if(r.freeGroup){const group=freeGroups.find(g=>g.id===r.freeGroup);group.root.add(o);applyTransform(o,r.transform);freeMembership.set(o,group);}else restorePiece(e,o,r);if(r.cut)applyPieceCut(e,o,r.cut);}}}

 setActive(e);return e;
}
async function addChosen(){if(busy)return;if(entries.length>=30){say('Limit 30 zestawów. Zapisz projekt lub usuń zestaw.');return;}remember();busy=true;$('#add').disabled=true;say('Wczytywanie wybranego modelu…');try{const e=await addEntry();if(renderer.xr.isPresenting)placeAhead(e);persist();say('Dodano model. Chwyć spustem fragment, gripem cały zestaw.');}catch(e){say('Nie udało się wczytać modelu. Spróbuj ponownie.');}finally{busy=false;$('#add').disabled=false;drawMenu();}}
function detachAny(entry,piece){piece.userData.pinned=false;delete piece.userData.boardId;if(freeMembership.has(piece)){entry.origin.attach(piece);freeMembership.delete(piece);}else detachPiece(entry,piece);}
function newFreeGroup(){if(selectedPiece)selectedPiece.updateWorldMatrix(true,false);if(freeGroups.length>=30){say('Limit 30 własnych grup.');return null;}const root=new THREE.Group(),g={id:crypto.randomUUID(),root};root.name=`Własna grupa ${freeGroups.length+1}`;root.userData.freeGroup=g.id;if(selectedPiece){root.position.copy(active.anchors.get(selectedPiece.name)).applyMatrix4(selectedPiece.matrixWorld);}content.add(root);freeGroups.push(g);activeFree=g;return g;}
function joinSelected(){if(!active||!selectedPiece){say('Najpierw wskaż i chwyć fragment.');return;}remember();releaseAll();if(layoutMode==='free'){const group=activeFree||newFreeGroup();if(!group)return;active.joined.delete(selectedPiece.name);group.root.attach(selectedPiece);freeMembership.set(selectedPiece,group);say('Dodano do własnej grupy BEZ zmiany położenia. Możesz dołączyć fragment z innej karty.');}else{detachAny(active,selectedPiece);joinPiece(active,selectedPiece);say('Element dołączony dokładnie według skanu.');}persist();}
function detachSelected(){if(!active||!selectedPiece){say('Najpierw wybierz fragment grupy.');return;}remember();releaseAll();detachAny(active,selectedPiece);persist();say('Element odłączony bez zmiany położenia. Możesz chwycić go osobno.');}
function assemble(){if(!active)return;remember();releaseAll();for(const p of active.pieces.filter(p=>p.visible)){detachAny(active,p);joinPiece(active,p);}persist();say('Przywrócono układ tej karty według skanu. Cofnij odzyskuje własne ułożenie.');}
const cutSides=[['xMin','od lewej'],['xMax','od prawej'],['yMax','od góry'],['yMin','od dołu'],['zMax','od przodu'],['zMin','od tyłu']];
function pieceBounds(piece){piece.updateWorldMatrix(true,true);const inverse=piece.matrixWorld.clone().invert(),box=new THREE.Box3();piece.traverse(m=>{if(!m.isMesh)return;const g=originalGeometry.get(m);g.computeBoundingBox();box.union(g.boundingBox.clone().applyMatrix4(inverse.clone().multiply(m.matrixWorld)));});return box;}
function applyPieceCut(entry,piece,cut){const full=pieceBounds(piece),size=full.getSize(new THREE.Vector3()),min=full.min.clone(),max=full.max.clone();for(let a=0;a<3;a++){const axis=['x','y','z'][a];min.setComponent(a,full.min.getComponent(a)+size.getComponent(a)*cut[axis+'Min']);max.setComponent(a,full.min.getComponent(a)+size.getComponent(a)*cut[axis+'Max']);}const box=new THREE.Box3(min,max),inverse=piece.matrixWorld.clone().invert();piece.traverse(m=>{if(!m.isMesh)return;const matrix=inverse.clone().multiply(m.matrixWorld),original=originalGeometry.get(m),source=original.clone().applyMatrix4(matrix);const cropped=cropGeometry(source,box);source.dispose();cropped.applyMatrix4(matrix.clone().invert());if(m.geometry!==original)m.geometry.dispose();m.geometry=cropped;});piece.userData.cut={...cut};const c=new THREE.Box3().setFromObject(piece).getCenter(new THREE.Vector3());piece.worldToLocal(c);entry.anchors.set(piece.name,c);}
function rotateSelected(axis,angle){if(busy||!active||!selectedPiece){say('Najpierw wybierz fragment.');return;}remember();releaseAll();detachAny(active,selectedPiece);rotateAroundAnchor(selectedPiece,axis,angle,active.anchors.get(selectedPiece.name));showSelectedPreview();persist();say('Obrócono fragment wokół osi '+['X','Y','Z'][axis]+'. Środek pozostaje na miejscu; część jest odłączona od grupy.');}
function changeCut(delta){if(busy||!active||!selectedPiece){say('Najpierw wybierz fragment.');return;}const cut={...FULL_CUT,...selectedPiece.userData.cut},key=cutSides[cutSide][0],axis=key[0];cut[key]=THREE.MathUtils.clamp(cut[key]+(key.endsWith('Min')?delta:-delta),0,1);if(!validCut(cut)){say('Pozostaw co najmniej 2% szerokości fragmentu.');return;}remember();releaseAll();detachAny(active,selectedPiece);applyPieceCut(active,selectedPiece,cut);showSelectedPreview();persist();say('Przycięto '+cutSides[cutSide][1]+'. Przywróć kształt lub Cofnij odwraca cięcie.');}
function resetCut(){if(busy||!active||!selectedPiece)return;remember();releaseAll();selectedPiece.traverse(m=>{if(!m.isMesh)return;const original=originalGeometry.get(m);if(m.geometry!==original)m.geometry.dispose();m.geometry=original;});delete selectedPiece.userData.cut;const c=new THREE.Box3().setFromObject(selectedPiece).getCenter(new THREE.Vector3());selectedPiece.worldToLocal(c);active.anchors.set(selectedPiece.name,c);showSelectedPreview();persist();say('Przywrócono pełny kształt i oryginalną teksturę. Ułożenie bez zmian.');}
function clonePiece(entry,source,name){const clone=source.clone(true);clone.name=name;clone.visible=true;clone.userData={entryId:entry.id,sourceName:source.userData.sourceName||source.name};const sourceMeshes=[];source.traverse(o=>{if(o.isMesh)sourceMeshes.push(o);});let i=0;clone.traverse(o=>{if(!o.isMesh)return;const base=sourceMeshes[i++],geometry=originalGeometry.get(base).clone(),pair=materialPairs.get(base),copy=m=>m.clone(),original=Array.isArray(pair.original)?pair.original.map(copy):copy(pair.original),flat=Array.isArray(pair.flat)?pair.flat.map(copy):copy(pair.flat);o.geometry=geometry;originalGeometry.set(o,geometry);materialPairs.set(o,{original,flat});o.material=readable?flat:original;});entry.origin.add(clone);entry.pieces.push(clone);entry.home.set(name,JSON.parse(JSON.stringify(entry.home.get(source.name))));entry.anchors.set(name,entry.anchors.get(source.name).clone());return clone;}
function splitSelected(){if(busy||!active||!selectedPiece){say('Najpierw wybierz fragment do podziału.');return;}if(active.pieces.length+splitCount>400){say('Limit części w zestawie. Zapisz projekt i pracuj w nowej pracowni.');return;}let ranges;try{ranges=splitRanges({...FULL_CUT,...selectedPiece.userData.cut},splitAxis,splitCount);}catch(e){say(e.message);return;}remember();releaseAll();const original=selectedPiece;detachAny(active,original);const pose=relativeTransform(original,active.origin),created=[];for(let i=0;i<ranges.length;i++){const child=clonePiece(active,original,`${original.userData.sourceName||original.name}__split_${crypto.randomUUID()}`);applyTransform(child,pose);applyPieceCut(active,child,ranges[i]);let vertices=0;child.traverse(m=>{if(m.isMesh)vertices+=m.geometry.attributes.position.count;});if(vertices){created.push(child);}else{child.visible=false;}}
 if(created.length<2){for(const child of created)child.visible=false;say('Ta linia nie przecina modelu na kilka części. Zmień oś. Cofnij usuwa próbę.');persist();return;}original.visible=false;setActive(active,created[0]);persist();say(`Podzielono na ${created.length} osobno chwytanych części. Bez przesuwania; możesz je teraz rozsunąć ręcznie.`);}
function toggleLayout(){layoutMode=layoutMode==='free'?'source':'free';persist();say(layoutMode==='free'?'Własny układ: brak przyciągania do skanu. Dołącz zachowuje Twoje położenie.':'Według skanu: przyciąganie łączy zgodnie ze źródłem.');}
function nextFreeGroup(){if(!freeGroups.length){newFreeGroup();}else activeFree=freeGroups[(freeGroups.indexOf(activeFree)+1)%freeGroups.length];drawMenu();}
function explode(){if(!active)return;remember();releaseAll();for(let i=0;i<active.pieces.length;i++){const p=active.pieces[i];if(!p.visible)continue;detachAny(active,p);joinPiece(active,p);detachPiece(active,p);const c=active.anchors.get(p.name).clone().applyMatrix4(p.matrix);let x=c.x,y=c.y;const length=Math.hypot(x,y)||1;p.position.x+=x/length*.18;p.position.y+=y/length*.18;p.position.z+=(i%5-2)*.055;}persist();say('Elementy odłączone i rozsunięte. Zielony cel oznacza gotowość do połączenia.');}
function updateVisibility(){for(const e of entries){if(e.ref)e.ref.visible=reference&&e===active;if(e.back)e.back.visible=backplate&&e===active;}}
function toggleBackplate(){backplate=!backplate;updateVisibility();persist();drawMenu();}
function toggleReadable(){readable=!readable;for(const e of entries)for(const p of e.pieces)p.traverse(m=>{if(m.isMesh)m.material=readable?materialPairs.get(m).flat:materialPairs.get(m).original;});persist();drawMenu();}
function scaleActive(f){if(!active)return;remember();const root=layoutMode==='free'&&selectedPiece&&freeMembership.get(selectedPiece)?.root||active.root;uniformScale(root,f);persist();say('Skala proporcjonalna: '+root.scale.x.toFixed(3)+' m / jednostkę źródła.');}
function placeAhead(e=active){if(!e)return;releaseAll();const target=(e===active&&selectedPiece&&freeMembership.get(selectedPiece)?.root)||e.root;const cam=renderer.xr.isPresenting?renderer.xr.getCamera():camera;cam.getWorldPosition(v3);cam.getWorldQuaternion(q4);const yaw=new THREE.Euler().setFromQuaternion(q4,'YXZ').y;const f=new THREE.Vector3(0,0,-1.05).applyAxisAngle(new THREE.Vector3(0,1,0),yaw);target.position.copy(v3).add(f);target.position.y=Math.max(.6,v3.y-.15);target.rotation.set(0,yaw,0);}
function toggleReference(){reference=!reference;updateVisibility();persist();drawMenu();}
function validate(data){if(data?.format!=='voynich-quest'||![1,2,3,4,5,6].includes(data.version)||!Array.isArray(data.entries)||data.entries.length>30)throw Error('Nieprawidłowy format projektu');const groups=data.freeGroups||[];if(!Array.isArray(groups)||groups.length>30||!groups.every(g=>typeof g.id==='string'&&validTransform(g.transform))||new Set(groups.map(g=>g.id)).size!==groups.length)throw Error('Nieprawidłowe grupy');const ids=new Set();for(const e of data.entries){if(typeof e.id!=='string'||ids.has(e.id)||!atlas.pages.some(p=>p.id===e.scan)||!['parts','page','whole','fragment'].includes(e.kind)||!validTransform(e.root)||(data.version>=2&&!validTransform(e.cluster))||!Array.isArray(e.pieces)||e.pieces.length>400||!e.pieces.every(p=>typeof p.name==='string'&&validTransform(p.transform)&&validCut(p.cut)&&(p.sourceName==null||typeof p.sourceName==='string')&&(p.visible===undefined||typeof p.visible==='boolean')&&(p.joined===undefined||typeof p.joined==='boolean')&&(!p.freeGroup||groups.some(g=>g.id===p.freeGroup))))throw Error('Nieprawidłowe modele lub współrzędne');ids.add(e.id);}return data;}
