$('#unpin').onclick=unpinSelected;$('#loupe').onclick=()=>study.toggleLoupe();$('#ambient').onclick=()=>study.toggleSound();$('#sourceOpen').onclick=()=>openResearchURL($('#sourceURL').value);$('#hypothesisSelect').onchange=()=>{study.hypothesis=Number($('#hypothesisSelect').value);study.drawPanel();};study.onHypothesis=h=>{$('#hypothesisSelect').value=String(study.hypothesis);$('#hypothesisStatus').textContent=h.status;$('#researchNote').value=study.notes[h.id]||'';};$('#researchNote').oninput=()=>{const h=study.research?.hypotheses[study.hypothesis];if(h){study.notes[h.id]=$('#researchNote').value.slice(0,2000);persist();}};$('#noteSave').onclick=()=>{const h=study.research?.hypotheses[study.hypothesis];if(h){study.notes[h.id]=$('#researchNote').value.slice(0,2000);persist();say('Notatka zapisana z projektem JSON.');}};
for(let i=0;i<2;i++){const controller=renderer.xr.getController(i);world.add(controller);const line=new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(),new THREE.Vector3(0,0,-1)]),new THREE.LineBasicMaterial({color:i?0xc8e69b:0x8fbfce,transparent:true,opacity:.7}));line.scale.z=3;controller.add(line);const handle=new THREE.Mesh(new THREE.CylinderGeometry(.016,.023,.09,8),new THREE.MeshStandardMaterial({color:i?0x91b779:0x7296ad}));handle.rotation.x=Math.PI/2;handle.position.z=-.015;controller.add(handle);const dot=new THREE.Mesh(new THREE.SphereGeometry(.006,8,6),new THREE.MeshBasicMaterial({color:0xd6edaa}));world.add(dot);dot.visible=false;const outline=new THREE.Box3Helper(new THREE.Box3(),0x8de2ff);outline.material.depthTest=false;outline.renderOrder=20;outline.visible=false;world.add(outline);const guide=new THREE.Line(new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(),new THREE.Vector3()]),new THREE.LineBasicMaterial({color:0x8de2ff,depthTest:false,transparent:true,opacity:.7}));guide.visible=false;world.add(guide);const h={controller,line,dot,outline,guide,ghost:null,ghostSource:null,held:null,input:null};hands.push(h);controller.addEventListener('connected',e=>h.input=e.data);controller.addEventListener('disconnected',()=>{release(h);h.input=null;clearAssist(h);persist();});controller.addEventListener('selectstart',()=>{h.triggerDown=true;begin(h,false);});controller.addEventListener('selectend',()=>{h.triggerDown=false;if(h.held&&!h.held.whole){release(h);persist();drawMenu();}});controller.addEventListener('squeezestart',()=>{h.gripDown=true;begin(h,true);});controller.addEventListener('squeezeend',()=>{h.gripDown=false;if(h.held?.whole){release(h);persist();drawMenu();}});}
async function enter(mode){if(busy||renderer.xr.isPresenting)return;let session=null,prepared=false;try{session=await navigator.xr.requestSession(mode,{requiredFeatures:['local-floor']});savedCamera.p.copy(camera.position);savedCamera.q.copy(camera.quaternion);savedCamera.target.copy(orbit.target);prepared=true;camera.position.set(0,0,0);camera.quaternion.identity();orbit.enabled=false;xrMode=mode;room.visible=false;study.setVisible(true,mode==='immersive-ar');world.background=mode==='immersive-vr'?new THREE.Color(0x15241b):null;renderer.setClearColor(0x000000,mode==='immersive-vr'?1:0);menu.visible=true;preview.root.visible=true;await renderer.xr.setSession(session);pendingCenter=3;session.addEventListener('end',()=>{releaseAll();persist();study.setVisible(false);room.visible=menu.visible=preview.root.visible=false;world.background=null;renderer.setClearColor(0,0);camera.position.copy(savedCamera.p);camera.quaternion.copy(savedCamera.q);orbit.target.copy(savedCamera.target);orbit.enabled=true;xrMode=null;hands.forEach(h=>{h.dot.visible=false;clearAssist(h);});say('Sesja zakończona. Praca zapisana lokalnie.');});say(mode==='immersive-ar'?'MR: widok otoczenia włączony.':'VR: pracownia włączona.');}catch(e){if(session)await session.end().catch(()=>{});if(prepared){study.setVisible(false);room.visible=menu.visible=preview.root.visible=false;world.background=null;renderer.setClearColor(0,0);camera.position.copy(savedCamera.p);camera.quaternion.copy(savedCamera.q);orbit.target.copy(savedCamera.target);orbit.enabled=true;xrMode=null;}say('Nie udało się uruchomić '+(mode==='immersive-ar'?'MR':'VR')+'. Otwórz stronę bezpośrednio w Meta Quest Browser i zezwól na sesję XR.');}}
async function detect(){if(!isSecureContext||!navigator.xr){$('#xrState').textContent='Podgląd 3D dostępny. VR / MR uruchom z tego adresu HTTPS w Meta Quest Browser.';return;}const [vr,ar]=await Promise.all(['immersive-vr','immersive-ar'].map(m=>navigator.xr.isSessionSupported(m).catch(()=>false)));$('#vr').disabled=!vr;$('#ar').disabled=!ar;$('#xrState').textContent=`Dostępne na tym urządzeniu: VR ${vr?'tak':'nie'}, MR ${ar?'tak':'nie'}.`;}
renderer.setAnimationLoop(time=>{const dt=Math.min(.05,Math.max(0,(time-lastTime)/1000));lastTime=time;preview.update(dt);study.update(time,[]);if(renderer.xr.isPresenting){if(pendingCenter>0&&!--pendingCenter){positionMenu();if(entries.length===1)placeAhead();}const help=[];for(const h of hands){if(!h.input){h.dot.visible=false;continue;}if(h.held){const axes=h.input.gamepad?.axes||[],y=axes.length>3?axes[3]:(axes[1]||0),x=axes.length>3?axes[2]:(axes[0]||0);if(Math.abs(x)>.2){const object=h.held.object,anchor=h.held.entry?.anchors.get(object.name)||new THREE.Vector3();rotateAroundAnchor(object,1,-x*dt*1.2,anchor);}if(Math.abs(y)>.2){h.held.object.position.z=THREE.MathUtils.clamp(h.held.object.position.z+y*dt*.6,-3,-.08);}}const hit=hits(h);study.inspect(hit,time);if(h.held?.object===study.glass){const r=new THREE.Raycaster();const g=study.glass;g.updateWorldMatrix(true,false);r.ray.origin.setFromMatrixPosition(g.matrixWorld);r.ray.direction.set(0,0,-1).applyQuaternion(g.getWorldQuaternion(new THREE.Quaternion()));study.inspect(r.intersectObjects(entries.flatMap(e=>e.pieces.filter(p=>p.visible)),true)[0],time+100);}h.line.scale.z=hit?Math.min(hit.distance,4):3;h.dot.visible=!!hit;if(hit)h.dot.position.copy(hit.point);const message=assist(h,hit);if(message)help.push(message);}assistText=help.join(' | ');if(time-lastMenuTime>180){drawMenu();lastMenuTime=time;}}else orbit.update();renderer.render(world,camera);});
let pointerStart=null;renderer.domElement.addEventListener('pointerdown',e=>pointerStart={x:e.clientX,y:e.clientY});renderer.domElement.addEventListener('pointerup',e=>{if(!pointerStart||Math.hypot(e.clientX-pointerStart.x,e.clientY-pointerStart.y)>5)return;const r=renderer.domElement.getBoundingClientRect();raycaster.setFromCamera(new THREE.Vector2((e.clientX-r.left)/r.width*2-1,-(e.clientY-r.top)/r.height*2+1),camera);const hit=raycaster.intersectObjects([...study.rayTargets(),...entries.flatMap(e=>e.pieces.filter(p=>p.visible))],true)[0];if(hit&&study.actionOf(hit.object)){const a=study.actionOf(hit.object);if(a.kind==='page')pluckPage(null,false,a.scan,hit.point.clone());else study.click(hit);return;}if(hit&&study.toolOf(hit.object)){const t=study.toolOf(hit.object);if(t===study.candle)study.toggleCandle();else if(t===study.glass)study.toggleLoupe();else if(t===study.overlay)study.applyOverlay(selectedPiece);else{study.measure=!study.measure;study.measurePoints=[];}return;}if(hit){if(study.measure&&study.measureHit(hit,entryOf(hit.object)?.scan+':'+pieceOf(entryOf(hit.object),hit.object)?.name))return;study.inspect(hit,performance.now());const entry=entryOf(hit.object);setActive(entry,pieceOf(entry,hit.object));say('Wybrano '+selectedPiece.name+' · '+(entry.joined.has(selectedPiece.name)?'połączony':'luźny'));}});
$('#rotate180').onclick=()=>rotateSelected(Number($('#rotateAxis').value),Math.PI);$('#splitAxis').onchange=()=>{splitAxis=$('#splitAxis').value;};$('#splitCount').onchange=()=>{splitCount=Number($('#splitCount').value);};$('#split').onclick=splitSelected;$('#showPreview').onclick=()=>{showSelectedPreview();};$('#category').onchange=()=>{category=$('#category').value;refreshCatalog();};$('#catalogSort').onchange=()=>{catalogSort=$('#catalogSort').value;refreshCatalog();};$('#previewPart').onchange=()=>{kind='parts';$('#kind').value=kind;previewPart=Number($('#previewPart').value);updatePreview();};$('#addPreview').onclick=addPreview;$('#rotateAxis').onchange=()=>{};$('#rotateMinus').onclick=()=>rotateSelected(Number($('#rotateAxis').value),-Math.PI/12);$('#rotatePlus').onclick=()=>rotateSelected(Number($('#rotateAxis').value),Math.PI/12);$('#cutSide').onchange=()=>{cutSide=Number($('#cutSide').value);drawMenu();};$('#cut').onclick=()=>changeCut(.05);$('#uncut').onclick=()=>changeCut(-.05);$('#resetCut').onclick=resetCut;
$('#layout').onclick=toggleLayout;$('#newGroup').onclick=()=>{remember();releaseAll();newFreeGroup();persist();drawMenu();};$('#join').onclick=joinSelected;$('#detach').onclick=detachSelected;$('#backplate').onclick=toggleBackplate;$('#reference').onclick=toggleReference;$('#readable').onclick=toggleReadable;$('#undo').onclick=undoAction;
$('#vr').onclick=()=>enter('immersive-vr');$('#ar').onclick=()=>enter('immersive-ar');$('#add').onclick=addChosen;$('#scan').onchange=()=>{cursor=atlas.pages.findIndex(p=>p.id===$('#scan').value);previewPart=-1;refreshParts();updatePreview();drawMenu();};$('#kind').onchange=()=>{changeKind($('#kind').value);};$('#explode').onclick=explode;$('#assemble').onclick=assemble;$('#save').onclick=()=>download(JSON.stringify(capture(),null,2),'manuskrypt-quest-projekt.json','application/json');$('#load').onclick=()=>$('#file').click();$('#file').onchange=async e=>{try{const f=e.target.files[0];if(!f||f.size>5e6)throw Error('Rozmiar');remember();await restore(JSON.parse(await f.text()));}catch{say('Nieprawidłowy plik projektu.');}e.target.value='';};$('#export').onclick=async()=>{if(!entries.length)return;releaseAll();try{say('Eksport GLB…');const result=await new GLTFExporter().parseAsync(content,{binary:true,onlyVisible:true});download(result,'manuskrypt-quest-scena.glb','model/gltf-binary');say('Scena wyeksportowana.');}catch{say('Eksport nie powiódł się. Zapisz projekt JSON.');}};
try{atlas=await(await fetch('assets/atlas.json')).json();await study.init(atlas);for(const [i,h] of study.research.hypotheses.entries()){const o=document.createElement('option');o.value=String(i);o.textContent=h.title;$('#hypothesisSelect').append(o);}study.drawPanel();for(const category of catalogCategories(atlas.pages)){const o=document.createElement('option');o.value=category;o.textContent=category;$('#category').append(o);}refreshCatalog();const saved=localStorage.getItem('voynich-quest-v1');if(saved){try{await restore(JSON.parse(saved));}catch{await addEntry();}}else await addEntry();$('#add').disabled=false;await detect();say('Gotowe. Wejdź do VR lub MR, aby składać modele kontrolerami.');}catch(e){say('Błąd wczytywania modeli. Odśwież stronę lub wróć do atlasu.');}
